func RenderFlagsJSON(flags []bool) (string, error) {
  n := len(flags)
  cflags := make([]C.int, n)
  for i, b := range flags { if b { cflags[i] = 1 } else { cflags[i] = 0 } }
  maxLen := C.size_t(256)
  buf := C.malloc(maxLen)
  if buf == nil { return "", errors.New("allocation failed") }
  defer C.free(buf)
  var ferr C.int
  C.render_flags_json((*C.int)(&cflags[0]), C.size_t(n), (*C.char)(buf), maxLen, &ferr)
  if ferr != 0 { return "", errors.New("render failed") }
  return C.GoString((*C.char)(buf)), nil
}
